    public function query_transactions_by_event_type(string $eventType, string $transactionType, string $methodName, ?string $code = null, ?int $since = null, ?int $limit = null, $params = array()): array {
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' ' . $methodName . '() requires walletAddress');
        }
        $this->load_markets();
        $currency = null;
        if ($code !== null) {
            $currency = $this->currency($code);
        }
        $subaccount = null;
        list($subaccount, $params) = $this->handle_option_and_params($params, $methodName, 'subaccount', 'default');
        $eventsRequest = array(
            'subaccounts' => array(
                $this->create_subaccount($this->walletAddress, $subaccount),
            ),
            'event_types' => array(
                $eventType,
            ),
            'limit' => array(
                'raw' => ($limit === null) ? 100 : min($limit, 500),
            ),
        );
        if ($currency !== null) {
            $eventsRequest['product_ids'] = array(
                $this->parse_to_int($currency['id']),
            );
        }
        list($eventsRequest, $params) = $this->handle_until_option('max_time', $eventsRequest, $params, 0.001);
        $request = array(
            'events' => $eventsRequest,
        );
        $response = $this->archivePost($this->deep_extend($request, $params));
        //
        //     {
        //         "events" => array(
        //             {
        //                 "subaccount" => "0x...",
        //                 "product_id" => 5,
        //                 "submission_idx" => "563011",
        //                 "event_type" => "deposit_collateral",
        //                 "pre_balance" => {
        //                     "spot" => {
        //                         "balance" => array(
        //                             "amount" => "1000000000000000000"
        //                         }
        //                     }
        //                 ),
        //                 "post_balance" => {
        //                     "spot" => {
        //                         "balance" => {
        //                             "amount" => "2000000000000000000"
        //                         }
        //                     }
        //                 }
        //             }
        //         ),
        //         "txs" => array(
        //             {
        //                 "submission_idx" => "563011",
        //                 "timestamp" => "1679728127"
        //             }
        //         )
        //     }
        //
        $events = $this->safe_list($response, 'events', array());
        $txs = $this->safe_list($response, 'txs', array());
        $transactions = array();
        for ($i = 0; $i < count($events); $i++) {
            $event = $events[$i];
            $submissionIdx = $this->safe_string($event, 'submission_idx');
            $tx = array();
            for ($j = 0; $j < count($txs); $j++) {
                $rawTx = $txs[$j];
                $txSubmissionIdx = $this->safe_string($rawTx, 'submission_idx');
                if ($txSubmissionIdx === $submissionIdx) {
                    $tx = $rawTx;
                    break;
                }
            }
            $transaction = $this->extend(array(), $tx);
            $transaction = $this->extend($transaction, $event);
            $transaction['transaction_type'] = $transactionType;
            $transactions[] = $this->parse_transaction($transaction, $currency);
        }
        return $this->filter_by_currency_since_limit($transactions, $code, $since, $limit);
    }

    public function fetch_positions(?array $symbols = null, $params = array()): array {
        /**
         * fetch all open $positions
         *
         * @see https://docs.nado.xyz/developer-resources/api/gateway/queries/subaccount-info
         *
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->subaccount] the 12-byte $subaccount identifier, defaults to 'default'
         * @return {Position[]} a list of ~@link https://docs.ccxt.com/#/?id=$position-structure $position structures~
         */
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' fetchPositions() requires walletAddress');
        }
        $this->load_markets();
        $symbols = $this->market_symbols($symbols);
        $subaccount = null;
        list($subaccount, $params) = $this->handle_option_and_params($params, 'fetchPositions', 'subaccount', 'default');
        $request = array(
            'type' => 'subaccount_info',
            'subaccount' => $this->create_subaccount($this->walletAddress, $subaccount),
        );
        $response = $this->gatewayPublicGetQuery($this->extend($request, $params));
        //
        //     {
        //         "status" => "success",
        //         "data" => {
        //             "perp_balances" => array(
        //                 {
        //                     "product_id" => 2,
        //                     "balance" => {
        //                         "amount" => "100000000000000000",
        //                         "v_quote_balance" => "3033500000000000000000",
        //                         "last_cumulative_funding_x18" => "-394223711772447555304"
        //                     }
        //                 }
        //             ),
        //             "perp_products" => array(
        //                 {
        //                     "product_id" => 2,
        //                     "oracle_price_x18" => "115596528090565357611177",
        //                     "risk" => array(
        //                         "price_x18" => "115596528090565357611177"
        //                     }
        //                 }
        //             )
        //         ),
        //         "request_type" => "query_subaccount_info"
        //     }
        //
        $data = $this->safe_dict($response, 'data', array());
        $positions = $this->safe_list($data, 'perp_balances', array());
        $products = $this->safe_list($data, 'perp_products', array());
        $result = array();
        for ($i = 0; $i < count($positions); $i++) {
            $position = $positions[$i];
            $balance = $this->safe_dict($position, 'balance', array());
            $amount = $this->safe_string($balance, 'amount');
            if (($amount === null) || Precise::string_equals($amount, '0')) {
                continue; // the endpoint returns an entry for every listed $product - only nonzero balances are open $positions
            }
            $productId = $this->safe_string($position, 'product_id');
            $product = array();
            for ($j = 0; $j < count($products); $j++) {
                $rawProduct = $products[$j];
                $rawProductId = $this->safe_string($rawProduct, 'product_id');
                if ($rawProductId === $productId) {
                    $product = $rawProduct;
                    break;
                }
            }
            $result[] = $this->parse_position($this->extend(array( 'product' => $product ), $position));
        }
        return $this->filter_by_array_positions($result, 'symbol', $symbols, false);
    }

    public function fetch_time($params = array()): ?int {
        /**
         * fetches the current integer timestamp in milliseconds from the exchange server
         *
         * @see https://docs.nado.xyz/developer-resources/api/gateway/edge#control-messages
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int} the current integer timestamp in milliseconds from the exchange server
         */
        $request = array(
            'type' => 'time',
        );
        $response = $this->gatewayPublicGetEdgeQuery($this->extend($request, $params));
        //
        //     {
        //         "status" => "success",
        //         "method" => "time",
        //         "id" => 2,
        //         "server_time" => "1780000000123"
        //     }
        //
        return $this->safe_integer($response, 'server_time');
    }

    public function fetch_status($params = array()) {
        /**
         * the latest known information on the availability of the exchange API
         *
         * @see https://docs.nado.xyz/developer-resources/api/gateway/queries/status
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=exchange-$status-structure $status structure~
         */
        $request = array(
            'type' => 'status',
        );
        $response = $this->gatewayPublicGetQuery($this->extend($request, $params));
        //
        //     {
        //         "status" => "success",
        //         "data" => "active",
        //         "request_type" => "query_status"
        //     }
        //
        $status = $this->safe_string($response, 'data');
        return array(
            'status' => ($status === 'active') ? 'ok' : 'error',
            'updated' => null,
            'eta' => null,
            'url' => null,
            'info' => $response,
        );
    }

    public function fetch_markets($params = array()): array {
        /**
         * retrieves data on all $markets for nado
         *
         * @see https://docs.nado.xyz/developer-resources/api/gateway/queries/symbols
         * @see https://docs.nado.xyz/developer-resources/api/v2/pairs
         * @see https://docs.nado.xyz/developer-resources/api/v2/assets
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing $market data
         */
        $symbolsRequest = $this->gatewayPublicGetSymbols($params);
        $pairsRequest = $this->gatewayV2PublicGetPairs($params);
        $assetsRequest = $this->gatewayV2PublicGetAssets($params);
        $responses = array( $symbolsRequest, $pairsRequest, $assetsRequest );
        $symbols = $this->safe_list($responses, 0, array());
        $pairs = $this->safe_list($responses, 1, array());
        $assets = $this->safe_list($responses, 2, array());
        // product_id is a JSON number => JS object keys are always strings but a Python
        // dict keeps int keys, so indexBy would never match the safeString lookups below
        $pairsById = array();
        for ($i = 0; $i < count($pairs); $i++) {
            $rawPair = $pairs[$i];
            $pairProductId = $this->safe_string($rawPair, 'product_id');
            if ($pairProductId !== null) {
                $pairsById[$pairProductId] = $rawPair;
            }
        }
        $assetsById = array();
        for ($i = 0; $i < count($assets); $i++) {
            $rawAsset = $assets[$i];
            $assetProductId = $this->safe_string($rawAsset, 'product_id');
            if ($assetProductId !== null) {
                $assetsById[$assetProductId] = $rawAsset;
            }
        }
        $assetsByCode = array();
        for ($i = 0; $i < count($assets); $i++) {
            $rawAsset = $assets[$i];
            $assetSymbol = $this->safe_string($rawAsset, 'symbol');
            $assetCode = $this->safe_currency_code($this->remove_market_suffix($assetSymbol));
            if ($assetCode === null) {
                continue;
            }
            $previous = $this->safe_dict($assetsByCode, $assetCode);
            if ($previous === null) {
                $assetsByCode[$assetCode] = $rawAsset;
            } else {
                $previousDeposit = $this->safe_bool($previous, 'can_deposit', false);
                $previousWithdraw = $this->safe_bool($previous, 'can_withdraw', false);
                $currentDeposit = $this->safe_bool($rawAsset, 'can_deposit', false);
                $currentWithdraw = $this->safe_bool($rawAsset, 'can_withdraw', false);
                if (!$previousDeposit && !$previousWithdraw && ($currentDeposit || $currentWithdraw)) {
                    $assetsByCode[$assetCode] = $rawAsset;
                }
            }
        }
        $markets = array();
        for ($i = 0; $i < count($symbols); $i++) {
            $market = $symbols[$i];
            $id = $this->safe_string($market, 'product_id');
            $pair = $this->safe_dict($pairsById, $id, array());
            $asset = $this->safe_dict($assetsById, $id, array());
            $rawType = $this->safe_string($market, 'type');
            $type = ($rawType === 'perp') ? 'swap' : $rawType;
            $contract = ($type === 'swap');
            $tickerId = $this->safe_string_2($pair, 'ticker_id', 'tickerId');
            if ($tickerId === null) {
                continue;
            }
            $rawBaseId = $this->safe_string($market, 'symbol');
            $rawQuoteId = $this->safe_string($pair, 'quote', 'USDT0');
            $base = $this->safe_currency_code($this->remove_market_suffix($rawBaseId));
            $quote = $this->safe_currency_code($rawQuoteId);
            $baseAsset = $this->safe_dict($assetsByCode, $base, $asset);
            $quoteAsset = $this->safe_dict($assetsByCode, $quote);
            $baseId = $this->safe_string($baseAsset, 'product_id', $rawBaseId);
            $quoteId = $this->safe_string($quoteAsset, 'product_id', $rawQuoteId);
            $settleId = $contract ? $quoteId : null;
            $settle = $contract ? $quote : null;
            $symbol = $base . '/' . $quote;
            if ($contract) {
                $symbol .= ':' . $settle;
            }
            $tradingStatus = $this->safe_string($market, 'trading_status');
            $active = ($tradingStatus !== 'not_tradable');
            $priceIncrement = $this->parse_x18($this->safe_string($market, 'price_increment_x18'));
            $amountIncrement = $this->parse_x18($this->safe_string($market, 'size_increment'));
            $minCost = $this->parse_x18($this->safe_string($market, 'min_size'));
            $markets[] = $this->safe_market_structure(array(
                'id' => $id,
                'lowercaseId' => null,
                'symbol' => $symbol,
                'base' => $base,
                'quote' => $quote,
                'settle' => $settle,
                'baseId' => $baseId,
                'quoteId' => $quoteId,
                'settleId' => $settleId,
                'type' => $type,
                'spot' => ($type === 'spot'),
                'margin' => null,
                'swap' => $contract,
                'future' => false,
                'option' => false,
                'active' => $active,
                'contract' => $contract,
                'linear' => $contract ? true : null,
                'inverse' => $contract ? false : null,
                'taker' => $this->parse_x18($this->safe_string($market, 'taker_fee_rate_x18')),
                'maker' => $this->parse_x18($this->safe_string($market, 'maker_fee_rate_x18')),
                'contractSize' => $contract ? 1 : null,
                'expiry' => null,
                'expiryDatetime' => null,
                'strike' => null,
                'optionType' => null,
                'precision' => array(
                    'amount' => $amountIncrement,
                    'price' => $priceIncrement,
                ),
                'limits' => array(
                    'leverage' => array(
                        'min' => null,
                        'max' => null,
                    ),
                    'amount' => array(
                        'min' => null,
                        'max' => null,
                    ),
                    'price' => array(
                        'min' => null,
                        'max' => null,
                    ),
                    'cost' => array(
                        'min' => $minCost,
                        'max' => null,
                    ),
                ),
                'created' => null,
                'info' => $this->extend($market, array(
                    'ticker_id' => $tickerId,
                    'name' => $this->safe_string($asset, 'name'),
                    'v2Pair' => $pair,
                    'v2Asset' => $asset,
                )),
            ));
        }
        return $markets;
    }

    public function fetch_currencies($params = array()): array {
        /**
         * fetches all available currencies on an exchange
         *
         * @see https://docs.nado.xyz/developer-resources/api/v2/assets
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an associative dictionary of currencies
         */
        $response = $this->gatewayV2PublicGetAssets($params);
        $result = array();
        for ($i = 0; $i < count($response); $i++) {
            $currency = $response[$i];
            $parsed = $this->parse_currency($currency);
            $code = $this->safe_string($parsed, 'code');
            if ($code === null) {
                continue;
            }
            $previous = $this->safe_dict($result, $code);
            $canDeposit = $this->safe_bool($currency, 'can_deposit', false);
            $canWithdraw = $this->safe_bool($currency, 'can_withdraw', false);
            if ($previous === null) {
                $result[$code] = $parsed;
            } else {
                $previousDeposit = $this->safe_bool($previous, 'deposit', false);
                $previousWithdraw = $this->safe_bool($previous, 'withdraw', false);
                if (!$previousDeposit && !$previousWithdraw && ($canDeposit || $canWithdraw)) {
                    $result[$code] = $parsed;
                }
            }
        }
        return $result;
    }

