        return array(
            $this->safe_timestamp($ohlcv, 'timestamp'),
            $this->parse_x18($this->safe_string($ohlcv, 'open_x18')),
            $this->parse_x18($this->safe_string($ohlcv, 'high_x18')),
            $this->parse_x18($this->safe_string($ohlcv, 'low_x18')),
            $this->parse_x18($this->safe_string($ohlcv, 'close_x18')),
            $this->parse_x18($this->safe_string($ohlcv, 'volume')),
        );
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        //
        //     {
        //         "product_id" => 1,
        //         "ticker_id" => "BTC-PERP_USDT0",
        //         "trade_id" => 6351,
        //         "price" => 112029.5896,
        //         "base_filled" => -0.388,
        //         "quote_filled" => 43467.4807648,
        //         "timestamp" => 1757335618,
        //         "trade_type" => "sell"
        //     }
        //
        // archive match
        //
        //     {
        //         "submission_idx" => "563012",
        //         "product_id" => 2,
        //         "timestamp" => "1679728133",
        //         "digest" => "0x80ce789702b670b7d33f2aa67e12c85f124395c3f9acdb422dde3b4973ccd50c",
        //         "order" => array(
        //             "priceX18" => "27544000000000000000000",
        //             "amount" => "2000000000000000000"
        //         ),
        //         "base_filled" => "736000000000000000",
        //         "quote_filled" => "-20276464287857571514302",
        //         "fee" => "4055287857571514302",
        //         "is_taker" => true
        //     }
        //
        $marketId = $this->safe_string($trade, 'product_id');
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_timestamp($trade, 'timestamp');
        $rawOrder = $this->safe_dict($trade, 'order');
        $isArchiveMatch = $rawOrder !== null;
        $order = ($rawOrder === null) ? array() : $rawOrder;
        $amountString = $this->safe_string($trade, 'base_filled');
        $costString = $this->safe_string($trade, 'quote_filled');
        $rawOrderAmount = $this->safe_string($order, 'amount');
        $side = $this->safe_string($trade, 'trade_type');
        if (($side === null) && ($rawOrderAmount !== null)) {
            if (Precise::string_lt($rawOrderAmount, '0')) {
                $side = 'sell';
            } else {
                $side = 'buy';
            }
        }
        $price = $this->safe_string($trade, 'price');
        if ($price === null) {
            $parsedPrice = $this->parse_x18($this->safe_string($order, 'priceX18'));
            $price = ($parsedPrice === null) ? null : $this->number_to_string($parsedPrice);
        }
        $takerOrMaker = null;
        $isTaker = $this->safe_bool($trade, 'is_taker');
        if ($isTaker !== null) {
            if ($isTaker) {
                $takerOrMaker = 'taker';
            } else {
                $takerOrMaker = 'maker';
            }
        }
        $feeString = $this->safe_string($trade, 'fee');
        $feeCost = null;
        if ($isArchiveMatch) {
            $feeCost = $this->parse_x18($feeString);
        } else {
            $feeCost = $this->parse_number($feeString);
        }
        $fee = null;
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $feeCost,
                'currency' => $market['quote'],
            );
        }
        $parsedAmount = null;
        if ($amountString !== null) {
            $absoluteAmount = Precise::string_abs($amountString);
            if ($isArchiveMatch) {
                $parsedAmount = $this->parse_x18($absoluteAmount);
            } else {
                $parsedAmount = $absoluteAmount;
            }
        }
        $parsedCost = null;
        if ($costString !== null) {
            $absoluteCost = Precise::string_abs($costString);
            if ($isArchiveMatch) {
                $parsedCost = $this->parse_x18($absoluteCost);
            } else {
                $parsedCost = $absoluteCost;
            }
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $market['symbol'],
            'id' => $this->safe_string_2($trade, 'trade_id', 'submission_idx'),
            'order' => $this->safe_string($trade, 'digest'),
            'type' => null,
            'side' => $side,
            'takerOrMaker' => $takerOrMaker,
            'price' => $price,
            'amount' => $parsedAmount,
            'cost' => $parsedCost,
            'fee' => $fee,
        ), $market);
    }

