    public function sign_hash(string $hash, ?string $privateKey) {
        if ($privateKey === null) {
            throw new ArgumentsRequired($this->id . ' signHash() requires privateKey');
        }
        $signature = $this->ecdsa(mb_substr($hash, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        $r = $signature['r'];
        $s = $signature['s'];
        $v = strtolower($this->int_to_base16($this->sum(27, $signature['v'])));
        return '0x' . $this->pad_hex($r, 64) . $this->pad_hex($s, 64) . $v;
    }

    public function remove_market_suffix(mixed $marketId) {
        if ($marketId === null) {
            return null;
        }
        if (str_ends_with($marketId, '-PERP')) {
            return mb_substr($marketId, 0, -5 - 0);
        }
        return $marketId;
    }

    public function sign(mixed $path, mixed $api = array(), $method = 'GET', $params = array(), mixed $headers = null, mixed $body = null) {
        $endpoint = $api[0];
        if (gettype($api) === 'string') {
            $endpoint = $api;
        }
        $url = $this->urls['api'][$endpoint];
        if ($path !== '') {
            $url .= '/' . $this->implode_params($path, $params);
        }
        $query = $this->omit($params, $this->extract_params($path));
        $headers = array();
        if (($endpoint === 'gateway') || ($endpoint === 'archive')) {
            $headers['Accept-Encoding'] = 'gzip, br, deflate';
        }
        if ($method === 'GET') {
            if ($query) {
                $url .= '?' . $this->urlencode($query);
            }
        } else {
            $headers['Content-Type'] = 'application/json';
            $body = $this->json($query);
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(?int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if (!$response) {
            return null; // fallback to default $error handler
        }
        //
        //     {
        //         "status" => "failure",
        //         "signature" => "0x...",
        //         "error_code" => 2007,
        //         "error" => "Order price must be within a range of 80% to 120% of oracle price.",
        //         "request_type" => "execute_place_order"
        //     }
        //
        $status = $this->safe_string($response, 'status');
        $errorCode = $this->safe_string($response, 'error_code');
        $error = $this->safe_string($response, 'error');
        if (($status === 'failure') || ($errorCode !== null) || ($error !== null)) {
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $error, $feedback);
            throw new ExchangeError($feedback); // unknown message
        }
        return null;
    }
}
